SET context_summary_from_message_id = #{fromMessageId},
    context_summary_to_message_id = #{toMessageId},
    context_summary_version = #{nextVersion},
    context_summary_hash = #{contentHash},
    context_summary_text = #{content}
WHERE conversation_id = #{conversationId}
  AND context_summary_version = #{expectedVersion}
